// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a non-depositor account
        address caller = address(0x1234);
        vm.prank(caller);

        // In reference contract this reverts due to onlyDepositor modifier
        // In mutant this succeeds because modifier is removed
        try c.setL1BlockValues(42, 100, 1000, bytes32(uint256(1)), 1, bytes32(uint256(2)), 100, 200) {
            // If no revert, mutant was used and number changed
            assertTrue(c.number() == 42, "Bug: non-depositor changed number");
            // This assert passes on mutant, fails on reference (reference reverts so never reaches here)
        } catch {
            // Revert happened - reference contract behavior
            assertTrue(true, "Reference: reverts on non-depositor call");
        }
    }
}
